package indexroom

import (
	"bytes"
	"encoding/json"
	"testing"
)

// oldExport is the pre-refactor implementation, kept here temporarily to
// prove the refactored Export produces identical bytes.
func oldExport(index *Index) []byte {
	index.mu.Lock()
	version := int64(snapshotVersion1)
	for height := int64(1); height <= index.Tip; height++ {
		if index.Blocks[height].Time != nil {
			version = snapshotVersion2
			break
		}
	}
	var raw []byte
	if version == snapshotVersion1 {
		type blockV1 struct {
			Height int64    `json:"height"`
			Hash   string   `json:"hash"`
			Parent string   `json:"parent"`
			Txs    []string `json:"txs"`
		}
		doc := struct {
			Version int64     `json:"version"`
			Tip     int64     `json:"tip"`
			Blocks  []blockV1 `json:"blocks"`
		}{Version: 1, Tip: index.Tip, Blocks: make([]blockV1, 0, int(index.Tip))}
		for height := int64(1); height <= index.Tip; height++ {
			block := index.Blocks[height]
			txs := make([]string, len(block.Txs))
			copy(txs, block.Txs)
			doc.Blocks = append(doc.Blocks, blockV1{block.Height, block.Hash, block.Parent, txs})
		}
		index.mu.Unlock()
		raw, _ = json.Marshal(doc)
	} else {
		type blockV2 struct {
			Height    int64    `json:"height"`
			Hash      string   `json:"hash"`
			Parent    string   `json:"parent"`
			Txs       []string `json:"txs"`
			Timestamp *int64   `json:"timestamp"`
		}
		doc := struct {
			Version int64     `json:"version"`
			Tip     int64     `json:"tip"`
			Blocks  []blockV2 `json:"blocks"`
		}{Version: 2, Tip: index.Tip, Blocks: make([]blockV2, 0, int(index.Tip))}
		for height := int64(1); height <= index.Tip; height++ {
			block := index.Blocks[height]
			txs := make([]string, len(block.Txs))
			copy(txs, block.Txs)
			entry := blockV2{Height: block.Height, Hash: block.Hash, Parent: block.Parent, Txs: txs}
			if block.Time != nil {
				t := *block.Time
				entry.Timestamp = &t
			}
			doc.Blocks = append(doc.Blocks, entry)
		}
		index.mu.Unlock()
		raw, _ = json.Marshal(doc)
	}
	return raw
}

func TestExportMatchesPreRefactorBytes(t *testing.T) {
	t0 := int64(0)
	tBig := int64(1700000000)
	chains := map[string][]Block{
		"empty": {},
		"v1 single no txs": {
			{Height: 1, Hash: "h1", Parent: "g"},
		},
		"v1 multi with dup/empty/case/whitespace txs": {
			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"dup", "", " Dup ", "dup"}},
			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{}},
			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a\tb", "q\"uote", "back\\slash", "雪", "́combining"}},
		},
		"v2 zero timestamp on tx-less block": {
			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"t1"}},
			{Height: 2, Hash: "h2", Parent: "h1", Time: &t0},
			{Height: 3, Hash: "h3", Parent: "h2", Time: &tBig},
		},
		"v2 timestamp on last block only": {
			{Height: 1, Hash: "h1", Parent: "g"},
			{Height: 2, Hash: "h2", Parent: "h1", Time: &tBig},
		},
		"v2 timestamp on first block only": {
			{Height: 1, Hash: "h1", Parent: "g", Time: &t0},
			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"x"}},
		},
		"v1 unicode identifiers": {
			{Height: 1, Hash: "雪", Parent: " ", Txs: []string{"�", "𐀀"}},
		},
	}
	for name, blocks := range chains {
		t.Run(name, func(t *testing.T) {
			index := New()
			for _, b := range blocks {
				if err := index.Append(b); err != nil {
					t.Fatalf("append: %v", err)
				}
			}
			var got bytes.Buffer
			if err := index.Export(&got); err != nil {
				t.Fatalf("export: %v", err)
			}
			if want := oldExport(index); !bytes.Equal(got.Bytes(), want) {
				t.Fatalf("bytes differ:\n got=%s\nwant=%s", got.Bytes(), want)
			}
			// The exported bytes must restore cleanly and re-export to the
			// same bytes.
			back := New()
			if err := back.Restore(bytes.NewReader(got.Bytes())); err != nil {
				t.Fatalf("restore: %v", err)
			}
			var again bytes.Buffer
			if err := back.Export(&again); err != nil {
				t.Fatalf("re-export: %v", err)
			}
			if !bytes.Equal(got.Bytes(), again.Bytes()) {
				t.Fatalf("round trip differs:\nfirst=%s\nagain=%s", got.Bytes(), again.Bytes())
			}
		})
	}
}
